const page = document.getElementById('page');
const nav = document.getElementById('mainNav');
const breadcrumb = document.getElementById('breadcrumb');
let currentRoute = 'dashboard';
let currentAsset = demoAssets[0];
let currentTrademark = trademarks[0];

function renderNav(){
  nav.innerHTML = navGroups.map(group => `<section class="nav-section"><span class="nav-label">${group.label}</span>${group.items.map(item => `<button class="nav-item ${item.id===currentRoute?'active':''}" data-route="${item.id}"><span class="nav-icon">${item.icon}</span><span>${item.text}</span>${item.count?`<b class="nav-count">${item.count}</b>`:''}</button>`).join('')}</section>`).join('');
}
function labelFor(route){ for(const group of navGroups){ const item=group.items.find(x=>x.id===route); if(item)return item.text; } return route==='asset-detail'?'档案详情':'页面'; }
function setBreadcrumb(title, parent='首页'){ breadcrumb.innerHTML=`<small>${parent}</small><span>›</span><strong>${title}</strong>`; document.title=`${title} · 知产云档原型`; }
function routeTo(route, options={}){
  currentRoute=route;
  if(options.asset) currentAsset=options.asset;
  if(options.trademark) currentTrademark=options.trademark;
  renderNav();
  document.getElementById('sidebar').classList.remove('open');
  const renderers={dashboard,assets:()=>assetList('all'),patents:()=>assetList('patent'),copyrights:()=>assetList('copyright'),trademarks:trademarksPage,materials:materialsPage,dates:datesPage,calendar:calendarPage,fees:feesPage,invoices:invoicesPage,analytics:analyticsPage,basics:basicsPage,system:systemPage,'asset-detail':assetDetail,'trademark-detail':trademarkDetail};
  (renderers[route]||dashboard)();
  window.location.hash=route;
  window.scrollTo({top:0,behavior:'smooth'});
}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function demoBadge(){return `<span class="badge purple">虚构示例数据</span>`}
function statusBadge(status){const c=status.includes('授权')||status.includes('登记')||status.includes('支付')?'green':status.includes('补正')||status.includes('待')?'amber':status.includes('失效')?'red':'';return `<span class="badge ${c}">${status}</span>`}
function pagination(count){return `<div class="pagination"><span>共 ${count} 条虚构记录 · 每页 10 条</span><div class="pages"><button class="page-btn">‹</button><button class="page-btn active">1</button><button class="page-btn">2</button><button class="page-btn">›</button></div></div>`}
function table(headers,rows){return `<div class="panel table-panel"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${pagination(rows.length)}</div>`}

