function openDrawer(type){const c=drawerConfig[type]||drawerConfig.basic;document.getElementById('drawerEyebrow').textContent=c.eyebrow;document.getElementById('drawerTitle').textContent=c.title;document.getElementById('drawerBody').innerHTML=`<div class="panel" style="padding:12px;margin-bottom:16px;background:#f8fbff"><small style="color:var(--muted)">${DEMO_NOTICE}。字段必填性、唯一性及部分枚举仍待正式确认。</small></div><div class="form-grid">${c.fields.map((f,i)=>{const full=f[1]==='textarea'||f[1]==='file';let control=f[1]==='select'?`<select>${f[2].split('|').map(x=>`<option>${x}</option>`).join('')}</select>`:f[1]==='textarea'?`<textarea placeholder="${f[2]}"></textarea>`:`<input type="${f[1]}" placeholder="${f[2]}">`;return `<div class="form-group ${full?'full':''}"><label>${f[0]}${i===0?' <span style="color:var(--red)">*</span>':''}</label>${control}${f[1]==='file'?'<small>原型不读取或上传真实文件</small>':''}</div>`}).join('')}</div>`;document.getElementById('drawerBackdrop').hidden=false;requestAnimationFrame(()=>document.getElementById('drawer').classList.add('open'));document.getElementById('drawer').setAttribute('aria-hidden','false');}
function closeDrawer(){document.getElementById('drawer').classList.remove('open');document.getElementById('drawer').setAttribute('aria-hidden','true');setTimeout(()=>document.getElementById('drawerBackdrop').hidden=true,220)}
function openPreview(file){document.getElementById('modalTitle').textContent=file;document.getElementById('modalBody').innerHTML=`<div class="panel" style="padding:10px;margin-bottom:12px"><span class="badge purple">虚构示例文件</span> <small style="color:var(--muted)">预览为前端占位，不包含真实文件内容</small></div><div class="document-preview"><div class="paper"><h3>示例材料文件</h3><p style="text-align:center">${file}</p><p>本页面用于展示知识产权材料预览区的视觉与交互方式。所有名称、编号、日期、主体和正文均为虚构示例，不代表真实专利、软件著作权或法律文件。</p><p>正式系统中，文件预览和下载需要经过服务端权限校验并写入审计日志。文件类型、大小与保存策略尚待确认。</p></div></div>`;document.getElementById('modalBackdrop').hidden=false;document.getElementById('modal').classList.add('open');document.getElementById('modal').setAttribute('aria-hidden','false')}
function closeModal(){document.getElementById('modal').classList.remove('open');document.getElementById('modal').setAttribute('aria-hidden','true');setTimeout(()=>document.getElementById('modalBackdrop').hidden=true,180)}
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;document.getElementById('toastStack').appendChild(el);setTimeout(()=>el.remove(),3200)}
function showDefinition(){openPreview('统计口径说明（原型）');document.getElementById('modalBody').innerHTML=`<div class="panel" style="box-shadow:none"><h3 style="margin-top:0">指标开发前必须确认</h3><div class="info-grid">${[['数据来源','对应业务表或接口'],['过滤条件','逻辑删除、类型、权限范围'],['日期字段','申请日 / 登记日等，待确认'],['去重规则','按稳定档案 ID'],['状态范围','综合状态映射待确认'],['空数据行为','显示 0 或空态，不生成伪数据']].map(x=>`<div class="info-item"><label>${x[0]}</label><span>${x[1]}</span></div>`).join('')}</div><div class="panel" style="margin-top:20px;background:#fff9ec"><strong style="font-size:11px">费用统计特别说明</strong><p style="font-size:10px;color:var(--muted)">应付金额、实付金额和发票含税金额不得混加。默认费用口径目前待确认，因此费用统计页不展示汇总数字。</p></div></div>`}
function bindDynamic(){page.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>routeTo(el.dataset.route));page.querySelectorAll('[data-drawer]').forEach(el=>el.onclick=()=>openDrawer(el.dataset.drawer));page.querySelectorAll('[data-asset]').forEach(el=>el.onclick=()=>routeTo('asset-detail',{asset:demoAssets.find(a=>a.id===el.dataset.asset)}));page.querySelectorAll('[data-trademark]').forEach(el=>el.onclick=()=>routeTo('trademark-detail',{trademark:trademarks.find(t=>t.id===el.dataset.trademark)||trademarks[0]}));page.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const action=el.dataset.action;if(action==='preview')openPreview(el.dataset.file);else if(action==='definition')showDefinition();else if(action==='toast')toast(el.dataset.message||DEMO_NOTICE);else if(action==='reset'){const inp=page.querySelector('[data-filter="asset"]');if(inp){inp.value='';inp.dispatchEvent(new Event('input'))}toast('已重置演示筛选条件');}else if(action==='filter')toast('已应用演示筛选条件','success');else toast(DEMO_NOTICE);});}

document.addEventListener('click',e=>{const item=e.target.closest('.nav-item');if(item)routeTo(item.dataset.route)});

document.getElementById('drawerClose').onclick=closeDrawer;document.getElementById('drawerCancel').onclick=closeDrawer;document.getElementById('drawerBackdrop').onclick=closeDrawer;document.getElementById('drawerSubmit').onclick=()=>{const required=document.querySelector('#drawerBody input');if(required&&!required.value){required.style.borderColor='var(--red)';toast('请填写第一个必填字段（表单校验示意）');return}toast('原型演示：已模拟保存，不会写入真实数据','success');closeDrawer()};
document.getElementById('modalClose').onclick=closeModal;document.getElementById('modalBackdrop').onclick=closeModal;
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){routeTo('assets');setTimeout(()=>{const input=page.querySelector('[data-filter="asset"]');if(input){input.value=e.target.value;input.dispatchEvent(new Event('input'))}},0)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();closeModal()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('globalSearch').focus()}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(r&&r!==currentRoute)routeTo(r)});
function init(){const r=location.hash.slice(1);routeTo(r&&['dashboard','assets','patents','copyrights','trademarks','materials','dates','calendar','fees','invoices','analytics','basics','system'].includes(r)?r:'dashboard');bindDynamic();}
const originalRouteTo=routeTo;routeTo=function(route,options={}){originalRouteTo(route,options);bindDynamic()};
init();
